# -*- coding: utf-8 -*-
"""City x service pages, part A: Sarasota, Siesta Key, Longboat Key, Palmer Ranch, Gulf Gate, Fruitville & Bee Ridge.
Every page is written for that locality and that service; the shared helper only assembles the frame."""
from _data import CITIES, SERVICES, cs_route
from _h import cap, sec, p, ul, table, note, cta, reviewed, svc_link, city_link, link, facts, cards
from templates import lead_form

SRC = "Planning band from the September 10, 2026 cost tables; not a quote."


def page(city, service, title, meta, h1, lede, capsule_q, capsule_a, diff_html, rules_html, example_html, local_q, local_a, resources):
    c, s = CITIES[city], SERVICES[service]
    pillar = ("Concrete", "/concrete/") if s["pillar"] == "concrete" else ("Pavers", "/pavers/")
    body = facts([("Jurisdiction", c["jurisdiction"]), ("Permit page", link(c["permit_route"], "rules and office")), ("Drive from Sarasota", c["drive"]), ("Service", svc_link(service))])
    body += cap(capsule_q, capsule_a, '<p class="src-note">' + SRC + '</p>')
    body += sec(f"What's different about {s['nav'].lower()} in {c['name']}", diff_html)
    body += sec("Rules that apply here", rules_html)
    body += sec("A worked example", example_html)
    body += cap(local_q, local_a)
    body += sec("Where to go next", cards([(s["route"], s["name"], "Full spec and FAQ."), (f"/areas/{city}/", c["name"], "Rules, ground, housing.")] + resources))
    body += sec(f"Request an estimate in {c['name']}", lead_form(city=c["name"], service=s["name"]))
    body += reviewed("September 10, 2026")
    return {"route": cs_route(city, service), "title": title, "meta_description": meta, "h1": h1, "kicker": f"{pillar[0]} · {c['name']}", "lede": lede,
            "breadcrumbs": [("Home", "/"), pillar, (s["name"], s["route"]), (c["name"], None)], "body_html": body, "faq": [(local_q, local_a)]}


